/* ==UserStyle==
@name           Showdown Plus - map 1: tower3-serpent
@namespace      dasmins.showdown.maps
@version        1.0.2
@description    One animated map of the battle background rotation (slot 1).
@homepageURL    https://github.com/dasmins/showdown-plus
@supportURL     https://github.com/dasmins/showdown-plus/issues
@updateURL      https://raw.githubusercontent.com/dasmins/showdown-plus/main/styles/maps/map01-tower3-serpent.user.css
@author         dasmins
==/UserStyle== */
/* ==========================================================================
   Showdown - animated tower3-serpent-640x410 background
   A separate Stylus style, so your main style stays quick to edit.
   Turn this style off in Stylus to go back to Showdown's own backgrounds.
   ========================================================================== */
@-moz-document domain("play.pokemonshowdown.com") {

  :root {
    /* MAP SLOT 1: this background is one of your maps. Each battle gets one installed map at random
       (the userscript picks; --map-pick in the main style can force one). To move it to another slot,
       change the number here and in the four data-ps-map="1" selectors further down */
    --map-1-on: 1;
    /* look of this background (1 = exactly as drawn). While your main style is on, its --bg-contrast,
       --bg-brightness and --bg-saturate are used instead of these three */
    --cbg-contrast: 1;
    --cbg-brightness: 1;
    --cbg-saturate: 1;
    /* haze + vignette from your main style on top of this background
       (0 = off, 1 = same as on Showdown's backgrounds, anything between = lighter) */
    --cbg-haze: 0;
  }

  /* this map's cast shadows (the Pokemon's and trainers' outlines laid on the ground) */
  html body .battle[data-ps-map="1"] {
    --map-shadow-angle: 52deg;       /* where they fall on screen: 0deg = right, 90deg = straight down (toward you), 180deg = left, 270deg = up (away) */
    --map-shadow-length: 1.1;        /* how long (1 = as long as the Pokemon is tall) */
    --map-shadow-strength: 0.5;      /* darkness (0 = none, 1 = black) */
    --map-shadow-blur: 1.5px;        /* softness of the edge */
  }

  /* the picture: replaces Showdown's background in the battles that get this map, drawn at exactly 2x (each half 320x205 -> 640x410) with
     sharp pixels. The pixelation from the main style is switched off here,
     because this is already finished pixel art (it also keeps the animation smooth). The main style's
     --bg-darks and --bg-lights do work on it (1 and 1 = as drawn, to within 2 of 255 colour levels). */
  html body .battle[data-ps-map="1"] .innerbattle > .backdrop {
    background-image: url("data:image/gif;base64,") !important;
    /* this picture is made for your 640x410 battle window, which shows x 50-690, y 40-450 of the 700x500
       backdrop: the padding leaves exactly that area, and the picture is drawn only there. It holds two versions,
       one above the other: the painted one (shown here) and the cel-shaded one (laid over it further down) */
    box-sizing: border-box !important;
    padding: 40px 10px 50px 50px !important;
    background-origin: content-box !important;
    background-clip: content-box !important;
    background-size: 100% 200% !important;
    background-position: 0 0 !important;
    background-repeat: no-repeat !important;
    image-rendering: pixelated !important;
    /* Showdown shows every background at 80% strength over a pale grey panel; this one is at full strength */
    opacity: 1 !important;
    filter:
      url(#ps-darks)
      url(#ps-lights)
      contrast(var(--cbg-contrast))
      brightness(var(--cbg-brightness))
      saturate(var(--cbg-saturate)) !important;
  }
  /* the cel-shaded version, over the painted one: --bg-cel in your main style sets how much of it shows
     (0 = as painted, 1 = fully cel-shaded, anything between = a blend; 1 if the main style does not set it) */
  html body .battle[data-ps-map="1"] .innerbattle > .backdrop::before {
    content: "" !important;
    position: absolute !important;
    left: 50px !important;
    top: 40px !important;
    width: 640px !important;
    height: 410px !important;
    background-image: inherit !important;      /* (the same picture as the backdrop's own) */
    background-size: 100% 200% !important;
    background-position: 0 100% !important;
    background-repeat: no-repeat !important;
    image-rendering: pixelated !important;
    opacity: var(--bg-cel, 1) !important;
    pointer-events: none !important;
  }
  html body .battle[data-ps-map="1"] .innerbattle > .backdrop::after {
    opacity: var(--cbg-haze) !important;
  }
}
